#!/usr/bin/env npx tsx
/**
 * Local test script for Lumos test generation.
 *
 * Runs generateTests() against a real Lighthouse PR.
 * Uses LiteLLM proxy for AI and Bitbucket DC for MCP.
 *
 * Prerequisites:
 *   Copy .env.example to .env and fill in your credentials.
 *
 * Usage:
 *   npx tsx scripts/test-gen-local.ts --pr 4700              # dry-run (default)
 *   npx tsx scripts/test-gen-local.ts --live --pr 4700        # live (calls AI, posts comment)
 *   npx tsx scripts/test-gen-local.ts --live --branch BZ-1234-feat  # resolve PR from branch
 *   npx tsx scripts/test-gen-local.ts --create-pr --pr 4700   # live + create test PR
 */

import { resolve } from 'node:path';
import { existsSync } from 'node:fs';
import { createLumos } from '../src/index.js';

// ---------------------------------------------------------------------------
// Load .env from project root (Node >= 20.12 built-in)
// ---------------------------------------------------------------------------
const projectRoot = resolve(import.meta.dirname, '..');
const envPath = resolve(projectRoot, '.env');

if (existsSync(envPath)) {
  process.loadEnvFile(envPath);
} else {
  console.error(
    'No .env file found. Copy .env.example to .env and fill in your credentials.'
  );
  process.exit(1);
}

// ---------------------------------------------------------------------------
// Validate required env vars
// ---------------------------------------------------------------------------
const required = [
  'LITELLM_BASE_URL',
  'LITELLM_API_KEY',
  'BITBUCKET_TOKEN',
  'BITBUCKET_USERNAME',
];
const missing = required.filter((k) => !process.env[k]);
if (missing.length > 0) {
  console.error(`Missing required env vars in .env: ${missing.join(', ')}`);
  process.exit(1);
}

// ---------------------------------------------------------------------------
// CLI args
// ---------------------------------------------------------------------------
const isLive = process.argv.includes('--live');
const isCreatePr = process.argv.includes('--create-pr');
const dryRun = !isLive && !isCreatePr;

function getArgValue(flag: string): string | undefined {
  const idx = process.argv.indexOf(flag);
  return idx !== -1 && process.argv[idx + 1]
    ? process.argv[idx + 1]
    : undefined;
}

const prId = getArgValue('--pr');
const branch = getArgValue('--branch');
const testType = getArgValue('--type') ?? 'mock';
const repoRoot = getArgValue('--repo-root');

if (!prId && !branch) {
  console.error(
    'Usage: npx tsx scripts/test-gen-local.ts --pr <id> [--live | --create-pr]\n' +
      '       npx tsx scripts/test-gen-local.ts --branch <name> [--live | --create-pr]'
  );
  process.exit(1);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  const mode = isCreatePr
    ? 'CREATE-PR (will call AI and create test branch + PR)'
    : isLive
      ? 'LIVE (will call AI and post PR comment)'
      : 'DRY RUN (no AI call, no PR comment)';

  console.log('=== Lumos Test Generation -- Local Test ===');
  console.log(`PR: ${prId ? `#${prId}` : '(resolve from branch)'}`);
  if (branch) console.log(`Branch: ${branch}`);
  console.log(`Mode: ${mode}`);
  console.log(`Type: ${testType}`);
  console.log(`Project root: ${projectRoot}`);
  console.log(`LiteLLM: ${process.env.LITELLM_BASE_URL}`);
  console.log(
    `Bitbucket: ${process.env.BITBUCKET_BASE_URL} as ${process.env.BITBUCKET_USERNAME}`
  );
  console.log('');

  const lumos = await createLumos(projectRoot);

  const result = await lumos.generateTests({
    workspace: 'BZ',
    repository: 'lighthouse',
    branch: branch ?? '',
    pullRequestId: prId ?? '',
    type: testType,
    dryRun,
    createPr: isCreatePr,
    ...(repoRoot ? { targetRepoRoot: repoRoot } : {}),
  });

  console.log('');
  console.log('=== Result ===');
  console.log(`Tests generated: ${result.testsGenerated}`);
  console.log(`Comments posted: ${result.commentsPosted}`);
  if (result.prUrl) {
    console.log(`PR created: ${result.prUrl}`);
  }
  if (result.jiraTicket) {
    console.log(`Jira ticket: ${result.jiraTicket}`);
  }
  if (result.durationMs != null) {
    console.log(`Duration: ${(result.durationMs / 1000).toFixed(1)}s`);
  }
  if (result.tokenUsage) {
    console.log(
      `Tokens: input=${result.tokenUsage.input}, output=${result.tokenUsage.output}, total=${result.tokenUsage.total}`
    );
  }
  if (result.estimatedCost != null) {
    console.log(`Estimated cost: $${result.estimatedCost.toFixed(4)}`);
  }
  if (result.toolsUsed && result.toolsUsed.length > 0) {
    console.log(`Tools used: ${result.toolsUsed.join(', ')}`);
  }

  if (result.rawResponse) {
    console.log('');
    console.log('=== Raw Response ===');
    console.log(result.rawResponse);
  }
}

main()
  .then(() => {
    process.exit(0);
  })
  .catch((err) => {
    console.error('Fatal error:', err);
    process.exit(1);
  });

#!/usr/bin/env npx tsx
/**
 * Local test script for Lumos.
 *
 * Runs Lumos against a fixture Playwright report for a given PR.
 * Uses LiteLLM proxy for AI and Bitbucket DC for MCP.
 *
 * Prerequisites:
 *   Copy .env.example to .env and fill in your credentials.
 *
 * Usage:
 *   npx tsx scripts/test-local.ts              # dry-run (default, PR 4598)
 *   npx tsx scripts/test-local.ts --live       # live run (calls AI, posts comment)
 *   npx tsx scripts/test-local.ts --live --pr 4598   # test against PR 4598
 */

import { resolve } from 'node:path';
import { existsSync } from 'node:fs';
import { createLumos } from '../src/index.js';

// ---------------------------------------------------------------------------
// Load .env from project root (Node >= 20.12 built-in)
// ---------------------------------------------------------------------------
const projectRoot = resolve(import.meta.dirname, '..');
const envPath = resolve(projectRoot, '.env');

if (existsSync(envPath)) {
  process.loadEnvFile(envPath);
} else {
  console.error(
    'No .env file found. Copy .env.example to .env and fill in your credentials.'
  );
  process.exit(1);
}

// ---------------------------------------------------------------------------
// Validate required env vars
// ---------------------------------------------------------------------------
const required = [
  'LITELLM_BASE_URL',
  'LITELLM_API_KEY',
  'BITBUCKET_TOKEN',
  'BITBUCKET_USERNAME',
];
const missing = required.filter((k) => !process.env[k]);
if (missing.length > 0) {
  console.error(`Missing required env vars in .env: ${missing.join(', ')}`);
  process.exit(1);
}

// ---------------------------------------------------------------------------
// CLI args
// ---------------------------------------------------------------------------
const isLive = process.argv.includes('--live');
const dryRun = !isLive;

// PR configurations
const PR_CONFIGS: Record<string, { branch: string; fixture: string }> = {
  '4598': {
    branch:
      'BZ-1200-enhance-video-generation-tool-to-direct-multiple-scenes-in-lighthouse',
    fixture: 'fixtures/result-4598.json',
  },
  '4638': {
    branch: 'BZ-1364-run-lumos-v-1-capability-verification',
    fixture: 'fixtures/result-4638.json',
  },
};

// Parse --pr flag (defaults to 4598)
const prFlagIndex = process.argv.indexOf('--pr');
const prId =
  prFlagIndex !== -1 && process.argv[prFlagIndex + 1]
    ? process.argv[prFlagIndex + 1]
    : '4598';

const prConfig = PR_CONFIGS[prId];
if (!prConfig) {
  console.error(
    `Unknown PR: ${prId}. Available: ${Object.keys(PR_CONFIGS).join(', ')}`
  );
  process.exit(1);
}

const fixturePath = resolve(projectRoot, prConfig.fixture);

async function main() {
  console.log('=== Lumos Local Test ===');
  console.log(`PR: #${prId} (${prConfig.branch})`);
  console.log(
    `Mode: ${dryRun ? 'DRY RUN (no AI call, no PR comment)' : 'LIVE (will call AI and post PR comment)'}`
  );
  console.log(`Project root: ${projectRoot}`);
  console.log(`Report fixture: ${fixturePath}`);
  console.log(`LiteLLM: ${process.env.LITELLM_BASE_URL}`);
  console.log(
    `Bitbucket: ${process.env.BITBUCKET_BASE_URL} as ${process.env.BITBUCKET_USERNAME}`
  );
  console.log('');

  const lumos = await createLumos(projectRoot);

  const result = await lumos.analyze({
    workspace: 'BZ',
    repository: 'lighthouse',
    branch: prConfig.branch,
    pullRequestId: prId,
    reportPath: fixturePath,
    type: 'mock',
    dryRun,
  });

  console.log('');
  console.log('=== Result ===');
  console.log(`Failures analyzed: ${result.failuresAnalyzed}`);
  console.log(`Comments posted: ${result.commentsPosted}`);
  console.log(`Has critical (PR-caused): ${result.hasCritical}`);
  if (result.finishReason != null) {
    console.log(`Finish reason: ${result.finishReason}`);
  }
  if (result.incomplete != null) {
    console.log(`Incomplete: ${result.incomplete}`);
  }
  if (result.fallbackPosted) {
    console.log(
      'Fallback: Comment posted via Bitbucket REST API (AI did not call add_comment)'
    );
  }
  if (result.attempts != null && result.attempts > 1) {
    console.log(`Attempts: ${result.attempts}`);
  }
  if (result.durationMs != null) {
    console.log(`Duration: ${(result.durationMs / 1000).toFixed(1)}s`);
  }
  if (result.tokenUsage) {
    console.log(
      `Tokens: input=${result.tokenUsage.input}, output=${result.tokenUsage.output}, total=${result.tokenUsage.total}`
    );
  }
  if (result.estimatedCost != null) {
    console.log(`Estimated cost: $${result.estimatedCost.toFixed(4)}`);
  }
  if (result.budgetExceeded) {
    console.log('WARNING: Budget exceeded!');
  }
  if (result.toolsUsed && result.toolsUsed.length > 0) {
    console.log(`Tools used: ${result.toolsUsed.join(', ')}`);
  }

  if (result.rawResponse) {
    console.log('');
    console.log('=== Raw Response ===');
    console.log(result.rawResponse);
  }
}

main()
  .then(() => {
    process.exit(0);
  })
  .catch((err) => {
    console.error('Fatal error:', err);
    process.exit(1);
  });

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const execSyncMock = vi.fn();

vi.mock('node:child_process', () => ({
  execSync: execSyncMock,
}));

vi.mock('node:fs', () => ({
  existsSync: vi.fn(() => true),
}));

const { gitFetch, gitPush } = await import('../src/utils/git-utils.js');

const str = (s: string) => ({ trim: () => s });

describe('gitFetch', () => {
  const cwd = '/repo';

  beforeEach(() => {
    execSyncMock.mockReset();
    delete process.env.BITBUCKET_USERNAME;
    delete process.env.BITBUCKET_TOKEN;
    delete process.env.BITBUCKET_BASE_URL;
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('falls back to plain fetch when credentials are not set', () => {
    execSyncMock.mockReturnValue(str(''));
    gitFetch('origin', cwd);
    expect(execSyncMock).toHaveBeenCalledOnce();
    expect(execSyncMock).toHaveBeenCalledWith(
      'git fetch origin',
      expect.any(Object)
    );
  });

  it('rewrites remote URL with credentials and restores it after fetch', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    const originalUrl = 'https://bitbucket.example.com/BZ/lighthouse.git';
    execSyncMock
      .mockReturnValueOnce(str(originalUrl)) // get-url
      .mockReturnValueOnce(str('')) // set-url (authed)
      .mockReturnValueOnce(str('')) // fetch
      .mockReturnValueOnce(str('')); // set-url (restore)

    gitFetch('origin', cwd);

    const calls = execSyncMock.mock.calls.map((c) => c[0] as string);
    expect(calls[0]).toBe('git remote get-url origin');
    expect(calls[1]).toContain('ci-user');
    expect(calls[1]).toContain('secret');
    expect(calls[1]).toContain('bitbucket.example.com');
    expect(calls[2]).toBe('git fetch origin');
    expect(calls[3]).toBe(`git remote set-url origin ${originalUrl}`);
    expect(calls[3]).not.toContain('secret');
  });

  it('restores the original remote URL even when fetch throws', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    const originalUrl = 'https://bitbucket.example.com/BZ/lighthouse.git';
    execSyncMock
      .mockReturnValueOnce(str(originalUrl)) // get-url
      .mockReturnValueOnce(str('')) // set-url (authed)
      .mockImplementationOnce(() => {
        throw new Error('network error');
      }) // fetch fails
      .mockReturnValueOnce(str('')); // set-url (restore — must still be called)

    expect(() => gitFetch('origin', cwd)).toThrow('network error');

    const restoreCall = execSyncMock.mock.calls[3]?.[0] as string;
    expect(restoreCall).toBeDefined();
    expect(restoreCall).toContain(originalUrl);
    expect(restoreCall).not.toContain('secret');
  });

  it('URL-encodes special characters in username and token', () => {
    process.env.BITBUCKET_USERNAME = 'user@domain.com';
    process.env.BITBUCKET_TOKEN = 'p@ss:word!';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    execSyncMock
      .mockReturnValueOnce(str('https://bitbucket.example.com/BZ/repo.git'))
      .mockReturnValue(str(''));

    gitFetch('origin', cwd);

    const setUrlCall = execSyncMock.mock.calls[1][0] as string;
    expect(setUrlCall).not.toContain('user@domain.com');
    expect(setUrlCall).toContain('user%40domain.com');
    expect(setUrlCall).not.toContain('p@ss:word!');
    expect(setUrlCall).toContain('p%40ss%3Aword!');
  });

  it('falls back to plain fetch when BITBUCKET_BASE_URL is malformed', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'not-a-valid-url';

    execSyncMock.mockReturnValue(str(''));
    gitFetch('origin', cwd);

    expect(execSyncMock).toHaveBeenCalledOnce();
    expect(execSyncMock).toHaveBeenCalledWith(
      'git fetch origin',
      expect.any(Object)
    );
  });

  it('falls back to plain fetch when remote URL host does not match BITBUCKET_BASE_URL', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    // Remote uses SSH — replace() will be a no-op
    execSyncMock
      .mockReturnValueOnce(str('git@bitbucket.example.com:BZ/repo.git')) // get-url
      .mockReturnValue(str(''));

    gitFetch('origin', cwd);

    const calls = execSyncMock.mock.calls.map((c) => c[0] as string);
    // should only call get-url + fetch — no set-url calls
    expect(calls).toHaveLength(2);
    expect(calls[1]).toBe('git fetch origin');
  });

  it('fetches a specific branch when branch param is provided (no credentials)', () => {
    execSyncMock.mockReturnValue(str(''));
    gitFetch('origin', cwd, 'feat/my-branch');
    expect(execSyncMock).toHaveBeenCalledOnce();
    expect(execSyncMock).toHaveBeenCalledWith(
      'git fetch origin feat/my-branch',
      expect.any(Object)
    );
  });

  it('fetches a specific branch with credential injection when branch param is provided', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    const originalUrl = 'https://bitbucket.example.com/BZ/lighthouse.git';
    execSyncMock
      .mockReturnValueOnce(str(originalUrl)) // get-url
      .mockReturnValueOnce(str('')) // set-url (authed)
      .mockReturnValueOnce(str('')) // fetch
      .mockReturnValueOnce(str('')); // set-url (restore)

    gitFetch('origin', cwd, 'feat/my-branch');

    const calls = execSyncMock.mock.calls.map((c) => c[0] as string);
    expect(calls[2]).toBe('git fetch origin feat/my-branch');
    expect(calls[3]).toBe(`git remote set-url origin ${originalUrl}`);
  });
});

describe('gitPush', () => {
  const cwd = '/repo';

  beforeEach(() => {
    execSyncMock.mockReset();
    delete process.env.BITBUCKET_USERNAME;
    delete process.env.BITBUCKET_TOKEN;
    delete process.env.BITBUCKET_BASE_URL;
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('injects credentials into remote URL before push and restores afterward', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    const originalUrl = 'https://bitbucket.example.com/BZ/lighthouse.git';
    execSyncMock
      .mockReturnValueOnce(str(originalUrl)) // get-url
      .mockReturnValueOnce(str('')) // set-url (authed)
      .mockReturnValueOnce(str('')) // push
      .mockReturnValueOnce(str('')); // set-url (restore)

    gitPush('test/my-branch', cwd);

    const calls = execSyncMock.mock.calls.map((c) => c[0] as string);
    expect(calls[0]).toBe('git remote get-url origin');
    expect(calls[1]).toContain('ci-user');
    expect(calls[1]).toContain('secret');
    expect(calls[2]).toContain('git push -u origin test/my-branch');
    expect(calls[3]).toBe(`git remote set-url origin ${originalUrl}`);
    expect(calls[3]).not.toContain('secret');
  });

  it('restores remote URL even when push throws', () => {
    process.env.BITBUCKET_USERNAME = 'ci-user';
    process.env.BITBUCKET_TOKEN = 'secret';
    process.env.BITBUCKET_BASE_URL = 'https://bitbucket.example.com';

    const originalUrl = 'https://bitbucket.example.com/BZ/lighthouse.git';
    execSyncMock
      .mockReturnValueOnce(str(originalUrl)) // get-url
      .mockReturnValueOnce(str('')) // set-url (authed)
      .mockImplementationOnce(() => {
        throw new Error('push failed');
      }) // push fails
      .mockReturnValueOnce(str('')); // set-url (restore)

    expect(() => gitPush('test/my-branch', cwd)).toThrow('push failed');

    const restoreCall = execSyncMock.mock.calls[3]?.[0] as string;
    expect(restoreCall).toBeDefined();
    expect(restoreCall).toContain(originalUrl);
    expect(restoreCall).not.toContain('secret');
  });
});

import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { NeuroLink } from '@juspay/neurolink';
import type { GenerateApiResult } from '@juspay/neurolink';
import { LumosOrchestrator } from '../src/orchestrator.js';
import type { LumosConfig } from '../src/config.js';
import type { AnalyzeOptions } from '../src/parsers/types.js';

const LUMOS_COMMENT = `## Lumos -- Test Failure Analysis (mock tests)

**Verdict: NEEDS FIXES**

0 passed | 1 failed | 0 flaky | 0m 1s

### Summary
One failure is caused by this PR.

